            float zinput = Input.GetAxisRaw("Mouse Y");
            float x = camPos.position.x;
            float z = camPos.position.z;
            float y = camPos.position.y;
            camNewPos = new Vector3(x + xinput, y, z + zinput);}
        //camPos.position = Vector3.MoveTowards(camPos.position, camNewPos, CamMoveSpeed * Time.deltaTime);
        camPos.position = Vector3.Lerp(camPos.position, camNewPos, CamMoveSpeed * Time.deltaTime);
    }
}

